@Composable
fun BottomNavItem(icon: ImageVector, label: String, isSelected: Boolean, onClick: () -> Unit) {
    val color = if (isSelected) Color(0xFFD47500) else Color.Gray
    Column(
        horizontalAlignment = Alignment.CenterHorizontally,
        modifier = Modifier.clickable { onClick() }
    ) {
        Icon(icon, contentDescription = label, tint = color)
        Text(label, style = MaterialTheme.typography.labelSmall, color = color)
    }
}

private data class CategoryUiDefinition(
    val name: String,
    val icon: ImageVector,
    val iconColor: Color
)

private fun parseDate(value: String): LocalDate? {
    return runCatching { LocalDate.parse(value) }.getOrNull()
}

private fun formatNumber(value: Double): String {
    val formatter = NumberFormat.getNumberInstance(Locale("vi", "VN"))
    formatter.maximumFractionDigits = 0
    formatter.minimumFractionDigits = 0
    return formatter.format(value)
}

private fun formatCurrency(value: Double): String {
    return "${formatNumber(abs(value))}đ"
}

private fun formatExpenseAmount(value: Double): String {
    return if (value <= 0.0) "0đ" else "-${formatCurrency(value)}"
}

private fun buildPercentText(current: Double, previous: Double): String {
    if (previous <= 0.0) {
        return if (current <= 0.0) "Không đổi" else "+100% so với tháng trước"
    }
    val change = ((current - previous) / previous) * 100
    val sign = if (change >= 0) "+" else ""
    val percent = String.format(Locale.US, "%.0f", change)
    return "$sign$percent% so với tháng trước"
}

private fun percentColor(current: Double, previous: Double): Color {
    if (previous <= 0.0) {
        return if (current <= 0.0) Color.Gray else Color(0xFFF44336)
    }
    return if (current <= previous) Color(0xFF4CAF50) else Color(0xFFF44336)
}

package com.example.billbuddy.ui.viewmodel

import androidx.lifecycle.ViewModel
import androidx.lifecycle.viewModelScope
import com.example.billbuddy.data.model.Expense
import com.example.billbuddy.data.repo.ExpenseRepository
import com.example.billbuddy.utils.Resource
import dagger.hilt.android.lifecycle.HiltViewModel
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.flow.launchIn
import kotlinx.coroutines.flow.onEach
import javax.inject.Inject

data class ExpenseUiState(
    val isLoading: Boolean = false,
    val expenses: List<Expense> = emptyList(),
    val errorMessage: String? = null
)

@HiltViewModel
class ExpenseViewModel @Inject constructor(
    private val expenseRepository: ExpenseRepository
) : ViewModel() {

    private val _expenseState = MutableStateFlow(ExpenseUiState())
    val expenseState: StateFlow<ExpenseUiState> = _expenseState.asStateFlow()

    private val _saveState = MutableStateFlow<Resource<Unit>?>(null)
    val saveState: StateFlow<Resource<Unit>?> = _saveState.asStateFlow()

    init {
        observeExpenses()
    }

    fun addExpense(date: String, category: String, amount: Double, note: String) {
        val expense = Expense(
            date = date,
            category = category,
            amount = amount,
            note = note,
            createdAt = System.currentTimeMillis()
        )

        expenseRepository.addExpense(expense).onEach { result ->
            _saveState.value = result
        }.launchIn(viewModelScope)
    }

    fun clearSaveState() {
        _saveState.value = null
    }

    private fun observeExpenses() {
        expenseRepository.observeExpenses().onEach { result ->
            when (result) {
                is Resource.Loading -> {
                    _expenseState.value = _expenseState.value.copy(isLoading = true, errorMessage = null)
                }
                is Resource.Success -> {
                    _expenseState.value = ExpenseUiState(
                        isLoading = false,
                        expenses = result.data.orEmpty(),
                        errorMessage = null
                    )
                }
                is Resource.Error -> {
                    _expenseState.value = ExpenseUiState(
                        isLoading = false,
                        expenses = result.data.orEmpty(),
                        errorMessage = result.message
                    )
                }
            }
        }.launchIn(viewModelScope)
    }
}
